80	func (c converter) toDomain(dbSpan *Span) (*model.Span, error) {
81		tags, err := c.fromDBTags(dbSpan.Tags)
82		if err != nil {
83			return nil, err
84		}
85		warnings, err := c.fromDBWarnings(dbSpan.Tags)
86		if err != nil {
87			return nil, err
88		}
89		logs, err := c.fromDBLogs(dbSpan.Logs)
90		if err != nil {
91			return nil, err
92		}
93		refs, err := c.fromDBRefs(dbSpan.Refs)
94		if err != nil {
95			return nil, err
96		}
97		process, err := c.fromDBProcess(dbSpan.Process)
98		if err != nil {
99			return nil, err
100		}
101		traceID := dbSpan.TraceID.ToDomain()
102		span := &model.Span{
103			TraceID: traceID,
104			//nolint:gosec // G115
105			SpanID:        model.NewSpanID(uint64(dbSpan.SpanID)),
106			OperationName: dbSpan.OperationName,
107			//nolint:gosec // G115
108			References: model.MaybeAddParentSpanID(traceID, model.NewSpanID(uint64(dbSpan.ParentID)), refs),
109			//nolint:gosec // G115
110			Flags: model.Flags(uint32(dbSpan.Flags)),
111			//nolint:gosec // G115
112			StartTime: model.EpochMicrosecondsAsTime(uint64(dbSpan.StartTime)),
113			//nolint:gosec // G115
114			Duration: model.MicrosecondsAsDuration(uint64(dbSpan.Duration)),
115			Tags:     tags,
116			Warnings: warnings,
117			Logs:     logs,
118			Process:  process,
119		}
120		return span, nil
121	}
