123	func (c converter) fromDBTags(tags []KeyValue) ([]model.KeyValue, error) {
124		retMe := make([]model.KeyValue, 0, len(tags))
125		for i := range tags {
126			if strings.HasPrefix(tags[i].Key, warningStringPrefix) {
127				continue
128			}
129			kv, err := c.fromDBTag(&tags[i])
130			if err != nil {
131				return nil, err
132			}
133			retMe = append(retMe, kv)
134		}
135		return retMe, nil
136	}
137	
138	func (c converter) fromDBWarnings(tags []KeyValue) ([]string, error) {
139		var retMe []string
140		for _, tag := range tags {
141			if !strings.HasPrefix(tag.Key, warningStringPrefix) {
142				continue
143			}
144			kv, err := c.fromDBTag(&tag)
145			if err != nil {
146				return nil, err
147			}
148			retMe = append(retMe, kv.VStr)
149		}
150		return retMe, nil
151	}
