153	func (converter) fromDBTag(tag *KeyValue) (model.KeyValue, error) {
154		switch tag.ValueType {
155		case stringType:
156			return model.String(tag.Key, tag.ValueString), nil
157		case boolType:
158			return model.Bool(tag.Key, tag.ValueBool), nil
159		case int64Type:
160			return model.Int64(tag.Key, tag.ValueInt64), nil
161		case float64Type:
162			return model.Float64(tag.Key, tag.ValueFloat64), nil
163		case binaryType:
164			return model.Binary(tag.Key, tag.ValueBinary), nil
165		default:
166			return model.KeyValue{}, fmt.Errorf("invalid ValueType in %+v", tag)
167		}
168	}
