170	func (c converter) fromDBLogs(logs []Log) ([]model.Log, error) {
171		retMe := make([]model.Log, len(logs))
172		for i, l := range logs {
173			fields, err := c.fromDBTags(l.Fields)
174			if err != nil {
175				return nil, err
176			}
177			retMe[i] = model.Log{
178				//nolint:gosec // G115
179				Timestamp: model.EpochMicrosecondsAsTime(uint64(l.Timestamp)),
180				Fields:    fields,
181			}
182		}
183		return retMe, nil
184	}
