186	func (converter) fromDBRefs(refs []SpanRef) ([]model.SpanRef, error) {
187		retMe := make([]model.SpanRef, len(refs))
188		for i, r := range refs {
189			refType, ok := dbToDomainRefMap[r.RefType]
190			if !ok {
191				return nil, fmt.Errorf("invalid SpanRefType in %+v", r)
192			}
193			retMe[i] = model.SpanRef{
194				RefType: refType,
195				TraceID: r.TraceID.ToDomain(),
196				//nolint:gosec // G115
197				SpanID: model.NewSpanID(uint64(r.SpanID)),
198			}
199		}
200		return retMe, nil
201	}
