214	func (converter) toDBTags(tags []model.KeyValue) []KeyValue {
215		retMe := make([]KeyValue, len(tags))
216		for i, t := range tags {
217			// do we want to validate a jaeger tag here? Making sure that the type and value matches up?
218			retMe[i] = KeyValue{
219				Key:          t.Key,
220				ValueType:    domainToDBValueTypeMap[t.VType],
221				ValueString:  t.VStr,
222				ValueBool:    t.Bool(),
223				ValueInt64:   t.Int64(),
224				ValueFloat64: t.Float64(),
225				ValueBinary:  t.Binary(),
226			}
227		}
228		return retMe
229	}
