// FromDBModel converts a slice of Cassandra dbmodel spans into OTel ptrace.Traces.
// Each dbmodel span becomes its own ResourceSpans entry.
func FromDBModel(spans []dbmodel.Span) ptrace.Traces {
	traceData := ptrace.NewTraces()
	if len(spans) == 0 {
		return traceData
	}
	dbSpansToSpans(spans, traceData.ResourceSpans())
	return traceData
}

func dbSpansToSpans(spans []dbmodel.Span, rss ptrace.ResourceSpansSlice) {
	rss.EnsureCapacity(len(spans))
	for i := range spans {
		rs := rss.AppendEmpty()
		dbProcessToResource(spans[i].Process, rs.Resource())
		dbSpanToInternal(spans[i], rs.ScopeSpans().AppendEmpty())
	}
}

func dbProcessToResource(process dbmodel.Process, dest pcommon.Resource) {
	if process.ServiceName == noServiceName {
		return
	}

	serviceName := process.ServiceName
	tags := process.Tags
	if serviceName == "" && tags == nil {
		return
	}

	attrs := dest.Attributes()
	if serviceName != "" {
		attrs.EnsureCapacity(len(tags) + 1)
		attrs.PutStr(otelsemconv.ServiceNameKey, serviceName)
	} else {
		attrs.EnsureCapacity(len(tags))
	}
	dbTagsToAttributes(tags, attrs)

	// Handle special keys translations.
	translateHostnameAttr(attrs)
	translateJaegerVersionAttr(attrs)
}

// translateHostnameAttr translates "hostname" atttribute
func translateHostnameAttr(attrs pcommon.Map) {
	hostname, hostnameFound := attrs.Get("hostname")
	_, convHostNameFound := attrs.Get(otelsemconv.HostNameKey)
	if hostnameFound && !convHostNameFound {
		hostname.CopyTo(attrs.PutEmpty(otelsemconv.HostNameKey))
		attrs.Remove("hostname")
	}
}

// translateHostnameAttr translates "jaeger.version" atttribute
func translateJaegerVersionAttr(attrs pcommon.Map) {
	jaegerVersion, jaegerVersionFound := attrs.Get("jaeger.version")
	_, exporterVersionFound := attrs.Get(attributeExporterVersion)
	if jaegerVersionFound && !exporterVersionFound {
		attrs.PutStr(attributeExporterVersion, "Jaeger-"+jaegerVersion.Str())
		attrs.Remove("jaeger.version")
	}
}

func dbSpanToInternal(span dbmodel.Span, ss ptrace.ScopeSpans) {
	dest := ss.Spans().AppendEmpty()
	dest.SetTraceID(pcommon.TraceID(span.TraceID))
	//nolint:gosec // G115
	dest.SetSpanID(idutils.UInt64ToSpanID(uint64(span.SpanID)))
	dest.SetName(span.OperationName)
	//nolint:gosec // G115
	dest.SetFlags(uint32(span.Flags))
	//nolint:gosec // G115
	dest.SetStartTimestamp(pcommon.Timestamp(span.StartTime * 1000))
	//nolint:gosec // G115
	dest.SetEndTimestamp(pcommon.Timestamp((span.StartTime + span.Duration) * 1000))

	parentSpanID := dbParentSpanID(span)
	if parentSpanID != 0 {
		//nolint:gosec // G115
		dest.SetParentSpanID(idutils.UInt64ToSpanID(uint64(parentSpanID)))
	}

	attrs := dest.Attributes()
	attrs.EnsureCapacity(len(span.Tags))
	dbTagsToAttributes(span.Tags, attrs)

	// Move the OTel instrumentation scope tags to the enclosing ScopeSpans.
	if nameAttr, ok := attrs.Get(otelsemconv.AttributeOtelScopeName); ok {
		ss.Scope().SetName(nameAttr.Str())
		attrs.Remove(otelsemconv.AttributeOtelScopeName)
		if versionAttr, ok := attrs.Get(otelsemconv.AttributeOtelScopeVersion); ok {
			ss.Scope().SetVersion(versionAttr.Str())
			attrs.Remove(otelsemconv.AttributeOtelScopeVersion)
		}
	}

	if spanKindAttr, ok := attrs.Get(model.SpanKindKey); ok {
		dest.SetKind(jSpanKindToInternal(spanKindAttr.Str()))
		attrs.Remove(model.SpanKindKey)
	}
	setSpanStatus(attrs, dest)

	dest.TraceState().FromRaw(getTraceStateFromAttrs(attrs))

	// drop the attributes slice if all of them were replaced during translation
	if attrs.Len() == 0 {
		attrs.Clear()
	}

	dbLogsToSpanEvents(span.Logs, dest.Events())
	dbReferencesToSpanLinks(span.Refs, parentSpanID, span.TraceID, dest.Links())
}

// dbParentSpanID returns the ID of the parent span if it exists. It searches
// for the first child-of or follows-from reference pointing to the same trace ID.
func dbParentSpanID(span dbmodel.Span) int64 {
	var followsFromRef *dbmodel.SpanRef
	for i := range span.Refs {
		ref := &span.Refs[i]
		if ref.TraceID != span.TraceID {
			continue
		}
		if ref.RefType == dbmodel.ChildOf {
			return ref.SpanID
		}
		if followsFromRef == nil && ref.RefType == dbmodel.FollowsFrom {
			followsFromRef = ref
		}
	}
	if followsFromRef != nil {
		return followsFromRef.SpanID
	}
	return 0
}

func dbTagsToAttributes(tags []dbmodel.KeyValue, dest pcommon.Map) {
	for _, tag := range tags {
		switch tag.ValueType {
		case dbmodel.StringType:
			dest.PutStr(tag.Key, tag.ValueString)
		case dbmodel.BoolType:
			dest.PutBool(tag.Key, tag.ValueBool)
		case dbmodel.Int64Type:
			dest.PutInt(tag.Key, tag.ValueInt64)
		case dbmodel.Float64Type:
			dest.PutDouble(tag.Key, tag.ValueFloat64)
		case dbmodel.BinaryType:
			dest.PutEmptyBytes(tag.Key).FromRaw(tag.ValueBinary)
		default:
			dest.PutStr(tag.Key, fmt.Sprintf("<Unknown Jaeger TagType %q>", tag.ValueType))
		}
	}
}

