)

const (
	noServiceName    = "OTLPResourceNoServiceName"
	eventNameAttr    = "event"
	statusError      = "ERROR"
	statusOk         = "OK"
	tagError         = "error"
	tagW3CTraceState = "w3c.tracestate"
	tagHTTPStatusMsg = "http.status_message"
)

// ToDBModel translates internal trace data into a slice of Cassandra dbmodel spans.
func ToDBModel(td ptrace.Traces) []dbmodel.Span {
	resourceSpans := td.ResourceSpans()

	if resourceSpans.Len() == 0 {
		return []dbmodel.Span{}
	}

	spans := make([]dbmodel.Span, 0, resourceSpans.Len())
	for i := 0; i < resourceSpans.Len(); i++ {
		rs := resourceSpans.At(i)
		spans = append(spans, resourceSpansToDbSpans(rs)...)
	}

	return spans
}

func resourceSpansToDbSpans(rs ptrace.ResourceSpans) []dbmodel.Span {
	resource := rs.Resource()
	ilss := rs.ScopeSpans()

	if ilss.Len() == 0 {
		return nil
	}

	process := resourceToDbProcess(resource)

	// Approximate the number of the spans as the number of the spans in the first
	// instrumentation library info.
	dbSpans := make([]dbmodel.Span, 0, ilss.At(0).Spans().Len())

	for i := 0; i < ilss.Len(); i++ {
		ils := ilss.At(i)
		spans := ils.Spans()
		for j := 0; j < spans.Len(); j++ {
			span := spans.At(j)
			dbSpans = append(dbSpans, spanToDbSpan(span, ils.Scope(), process))
		}
	}

	return dbSpans
}

func resourceToDbProcess(resource pcommon.Resource) dbmodel.Process {
	process := dbmodel.Process{}
	attrs := resource.Attributes()
	if attrs.Len() == 0 {
		process.ServiceName = noServiceName
		return process
	}
	attrsCount := attrs.Len()
	if serviceName, ok := attrs.Get(otelsemconv.ServiceNameKey); ok {
		process.ServiceName = serviceName.Str()
		attrsCount--
	}
	if attrsCount == 0 {
		return process
	}

	tags := make([]dbmodel.KeyValue, 0, attrsCount)
	process.Tags = appendTagsFromResourceAttributes(tags, attrs)
	return process
}

func appendTagsFromResourceAttributes(dest []dbmodel.KeyValue, attrs pcommon.Map) []dbmodel.KeyValue {
	if attrs.Len() == 0 {
		return dest
	}

	for key, attr := range attrs.All() {
		if key == otelsemconv.ServiceNameKey {
			continue
		}
		dest = append(dest, attributeToDbTag(key, attr))
	}
	return dest
}

func appendTagsFromAttributes(dest []dbmodel.KeyValue, attrs pcommon.Map) []dbmodel.KeyValue {
	if attrs.Len() == 0 {
		return dest
	}
	for key, attr := range attrs.All() {
		dest = append(dest, attributeToDbTag(key, attr))
	}
	return dest
}

func attributeToDbTag(key string, attr pcommon.Value) dbmodel.KeyValue {
	tag := dbmodel.KeyValue{Key: key}
	switch attr.Type() {
	case pcommon.ValueTypeInt:
		tag.ValueType = dbmodel.Int64Type
		tag.ValueInt64 = attr.Int()
	case pcommon.ValueTypeBool:
		tag.ValueType = dbmodel.BoolType
		tag.ValueBool = attr.Bool()
	case pcommon.ValueTypeDouble:
		tag.ValueType = dbmodel.Float64Type
		tag.ValueFloat64 = attr.Double()
	case pcommon.ValueTypeBytes:
		tag.ValueType = dbmodel.BinaryType
		tag.ValueBinary = attr.Bytes().AsRaw()
	case pcommon.ValueTypeMap, pcommon.ValueTypeSlice:
		tag.ValueType = dbmodel.StringType
		tag.ValueString = attr.AsString()
	default:
		tag.ValueType = dbmodel.StringType
		tag.ValueString = attr.Str()
	}
	return tag
}

func spanToDbSpan(span ptrace.Span, scope pcommon.InstrumentationScope, process dbmodel.Process) dbmodel.Span {
	traceID := dbmodel.TraceID(span.TraceID())
	refs := makeDbReferences(span.Links(), spanIDToDb(span.ParentSpanID()), traceID)

	//nolint:gosec // G115
	startTime := int64(span.StartTimestamp()) / 1000
	//nolint:gosec // G115
	duration := (int64(span.EndTimestamp()) - int64(span.StartTimestamp())) / 1000

