import (
	"bytes"
	"encoding/json"
	"fmt"
	"os"

	"go.opentelemetry.io/collector/pdata/ptrace"

	"github.com/jaegertracing/jaeger/internal/storage/v1/cassandra/spanstore/dbmodel"
	"github.com/jaegertracing/jaeger/internal/storage/v2/cassandra/tracestore"
)

const dir = "internal/storage/v2/cassandra/tracestore/fixtures/"

func main() {
	casData, err := os.ReadFile(dir + "cas_01.json")
	must(err)
	otelData, err := os.ReadFile(dir + "otel_traces_01.json")
	must(err)

	// FromDBModel(cas) == otel
	var spans []dbmodel.Span
	must(json.Unmarshal(casData, &spans))
	td := tracestore.FromDBModel(spans)

	um := ptrace.JSONUnmarshaler{}
	expectedTd, err := um.UnmarshalTraces(otelData)
	must(err)
	m := ptrace.JSONMarshaler{}
	a, _ := m.MarshalTraces(td)
	b, _ := m.MarshalTraces(expectedTd)
	if !bytes.Equal(a, b) {
		fmt.Println("MISMATCH: FromDBModel(cas) != otel")
		fmt.Println(string(a))
		os.Exit(1)
	}
	fmt.Println("OK: FromDBModel(cas) == otel")

	// ToDBModel(otel) re-encoded == cas file bytes
	actualSpans := tracestore.ToDBModel(expectedTd)
	buf := &bytes.Buffer{}
	enc := json.NewEncoder(buf)
	enc.SetIndent("", "  ")
	must(enc.Encode(actualSpans))
	if buf.String() != string(casData) {
		fmt.Println("MISMATCH: encoded ToDBModel(otel) != cas file")
		fmt.Printf("got len=%d want len=%d\n", buf.Len(), len(casData))
		os.Exit(1)
	}
	fmt.Println("OK: ToDBModel(otel) re-encoded == cas file bytes")
}

func must(err error) {
	if err != nil {
		panic(err)
	}
}
